import{_ as t,o as a,c as o,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const i=JSON.parse('{"title":"2009年 · 危机中的坚守","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2009年.md","filePath":"05_quotes/by-year/2009年.md"}'),r={name:"05_quotes/by-year/2009年.md"};function s(c,e,u,h,_,q){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="_2009年-·-危机中的坚守" tabindex="-1">2009年 · 危机中的坚守 <a class="header-anchor" href="#_2009年-·-危机中的坚守" aria-label="Permalink to &quot;2009年 · 危机中的坚守&quot;">​</a></h1><blockquote><p>在别人恐惧时贪婪，在别人贪婪时恐惧。——巴菲特（79岁）</p></blockquote><p>本页收录2009年致股东信中的经典语录。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>我只想知道我会死在哪里，这样我就永远不去那里。——查理·芒格</p></blockquote><blockquote><p>逆向思考，始终逆向思考。</p></blockquote><blockquote><p>防守优于进攻，这一特点大概率延续。</p></blockquote><blockquote><p>&quot;大而不倒&quot;不是我们的退路。我们始终确保：任何可能的现金需求，与自身流动性相比都微不足道。</p></blockquote><blockquote><p>2008年9月金融体系停摆时，伯克希尔哈撒韦是流动性与资本的提供者，而非求助者。危机最严峻时刻，我们向市场投入155亿美元。</p></blockquote><blockquote><p>恐惧氛围是最好的朋友。只在评论乐观时投资的人，最终会为毫无意义的安全感付出沉重代价。</p></blockquote><blockquote><p>你为生意支付的价格，与未来十年、二十年生意赚取的利润。</p></blockquote><blockquote><p>巨额资金会自己铸造枷锁，我们未来的优势将只是历史优势的一小部分。</p></blockquote><blockquote><p>如果查理、我和阿吉特在同一条沉船上，你只能救一个人——游向阿吉特。</p></blockquote><blockquote><p>我们宁可承担少数错误决策的显性成本，也不愿承受因官僚僵化导致决策迟缓、甚至不决策的隐性成本。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2009年是金融危机后全球经济复苏的起点。伯克希尔哈撒韦净资产增加218亿美元，每股账面价值增长19.8%，过去45年复合年化收益率达20.3%。巴菲特在危机最严峻时刻果断投入155亿美元，成为市场的流动性提供者。同年完成收购伯灵顿北方圣达菲铁路公司（BNSF），这是伯克希尔历史上最大的收购之一。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-2009年-翻译-·-01-letters-2009年-核心总结-·-01-letters-2009年-思维导图" tabindex="-1"><a href="/01_letters/2009年/翻译.html">01_letters/2009年/翻译</a> · <a href="/01_letters/2009年/核心总结.html">01_letters/2009年/核心总结</a> · <a href="/01_letters/2009年/思维导图.html">01_letters/2009年/思维导图</a> <a class="header-anchor" href="#_01-letters-2009年-翻译-·-01-letters-2009年-核心总结-·-01-letters-2009年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/2009年/翻译]] · [[→ 核心总结|01_letters/2009年/核心总结]] · [[→ 思维导图|01_letters/2009年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/2009年/翻译.html">/01_letters/2009年/翻译</a></li></ul>',23)])])}const p=t(r,[["render",s]]);export{i as __pageData,p as default};
